import{L as e,b as t,x as n}from"./vue-Vea_iehr.js";import{oi as r}from"./common-BF76nj_i.js";var i=JSON.parse(`{"path":"/vm/esxi/m5zuxupu/","title":"ESXi 直通 SATA 控制器 | ESXi","lang":"zh-CN","frontmatter":{"title":"ESXi 直通 SATA 控制器","tags":["pci","esxi","vm"],"createTime":"2026/08/24 22:27:23","permalink":"/vm/esxi/m5zuxupu/"},"readingTime":{"minutes":2.19,"words":658},"git":{},"filePathRelative":"vm/esxi/002.passthrough-sata-controller.md","headers":[]}`),a={name:`002.passthrough-sata-controller.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="pci-设备直通" tabindex="-1"><a class="header-anchor" href="#pci-设备直通"><span>PCI 设备直通</span></a></h2><p>VMware ESXi 提供两种层次的硬件直通能力，其中 PCI 设备直通（又称 DirectPath I/O）是把整块物理控制器直接分配给虚拟机使用，绕过 hypervisor 的磁盘抽象层。本文以 SATA 控制器为例，记录从识别设备到启用直通的全过程。</p><h3 id="识别目标设备" tabindex="-1"><a class="header-anchor" href="#识别目标设备"><span>识别目标设备</span></a></h3><p>先确认主机上的 SATA 控制器及其 PCI ID：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lspci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Class 0106&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div><p>输出示例：</p><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">0000:00:17.0 Mass storage controller SATA controller: Intel Corporation Comet Lake SATA AHCI Controller</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">         Class 0106: 8086:06d2</span></span></code></pre></div><p><code>Class 0106</code> 即 SATA 存储控制器类代码，本例中厂商/设备 ID 为 <code>8086:06d2</code>。</p><h3 id="编辑-passthru-map" tabindex="-1"><a class="header-anchor" href="#编辑-passthru-map"><span>编辑 passthru.map</span></a></h3><p>ESXi 通过 <code>/etc/vmware/passthru.map</code> 维护 PCI 设备直通名单，按 <code>厂商ID 设备ID 子系统ID 是否启用MSI</code> 的格式逐行登记：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/vmware/passthru.map</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 追加一行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">8086</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   06d2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    d3d0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    false</span></span></code></pre></div><p>各字段含义：</p><div class="language-" data-highlighter="shiki" data-ext="" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-"><span class="line"><span>VendorID  DeviceID  SubsystemID  passthru</span></span></code></pre></div><ul><li><code>8086</code>：Intel 厂商 ID</li><li><code>06d2</code>：设备 ID</li><li><code>d3d0</code>：子系统 ID 占位值，此处任意填写均可</li><li><code>false</code>：不启用 MSI/MSI-X 中断映射，部分设备直通后需要关闭才能正常工作</li></ul><h3 id="验证与启用" tabindex="-1"><a class="header-anchor" href="#验证与启用"><span>验证与启用</span></a></h3><p>重启前可在 ESXi Shell 中确认设备是否进入直通就绪状态：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vmkchdev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 06d2</span></span></code></pre></div><p>对目标设备启用直通（修改 passthru.map 后需执行）：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vmkchdev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0000:00:17.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span></span></code></pre></div><p>完成后重启 ESXi，在虚拟机设置的「添加 PCI 设备」中选择该控制器即可。</p><h3 id="注意事项" tabindex="-1"><a class="header-anchor" href="#注意事项"><span>注意事项</span></a></h3><ol><li>控制器被直通后，其下挂载的所有物理硬盘将不再被 ESXi 识别，只能由对应虚拟机独占访问。</li><li>部分主板 SATA 控制器不具备独立 IOMMU 分组，会导致直通失败或连带影响其他设备。</li><li>直通生效依赖硬件支持 ACS/IOMMU，操作前建议在 BIOS 中确认 VT-d 已开启。</li></ol><h3 id="与-rdm-的取舍" tabindex="-1"><a class="header-anchor" href="#与-rdm-的取舍"><span>与 RDM 的取舍</span></a></h3><p>若只想把单块硬盘交给虚拟机而非整块控制器，可考虑 RDM（Raw Device Mapping），二者定位不同：</p><table><thead><tr><th>方案</th><th>用途</th><th>适用场景</th></tr></thead><tbody><tr><td>PCI Passthrough</td><td>直通整个 SATA/NVMe 控制器</td><td>高性能、ZFS、软 RAID 场景</td></tr><tr><td>RDM</td><td>直通单块物理硬盘</td><td>精细控制单块磁盘映射</td></tr></tbody></table><h2 id="rdm-原始设备映射" tabindex="-1"><a class="header-anchor" href="#rdm-原始设备映射"><span>RDM 原始设备映射</span></a></h2><p>RDM 不直通控制器，而是在 ESXi 层为某块物理硬盘创建一枚指向它的 <code>.vmdk</code> 映射文件，虚拟机通过这块映射盘访问真实磁盘。建立映射使用 <code>vmkfstools -z</code>：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vmkfstools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -z</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /vmfs/devices/disks/t10.ATA_____Disk123456</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /vmfs/volumes/datastore1/vmname/disk1.vmdk</span></span></code></pre></div><p>映射盘创建后，将其作为现有硬盘添加到虚拟机即可，底层磁盘路径保持不变。</p>`,29)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};